  'plans.storageWarning': 'আপনি {used} এর মধ্যে {total} ব্যবহার করছেন',
  'plans.storageWarningUpgrade': 'Chatyy One-এ আপগ্রেড করুন এবং 200 GB পান!',
  'plans.faqWhatIsPlus': 'Chatyy One কি?',
  'plans.faqWhatIsPlusAnswer': 'এটি Chatyy-এর প্রিমিয়াম পরিকল্পনা যা আপনার সমস্ত কথোপকথন, ছবি এবং ভিডিও সুরক্ষিত রাখে। Chatyy One-এর সাথে, আপনি যদি কিছু ভুলে মুছে ফেলেন, তবে 30 দিনের মধ্যে এটি পুনরুদ্ধার করতে পারেন। এছাড়াও, আপনি 200GB স্টোরেজ, One AI আপনার ব্যক্তিগত সহকারী হিসেবে পাবেন, এবং 100MB পর্যন্ত ফাইল পাঠাতে পারবেন।',
  'plans.faqCancelAnswer': 'আপনার পরিকল্পনা পরিশোধিত সময়সীমা শেষ হওয়া পর্যন্ত সক্রিয় থাকবে। এর পরে, আপনি বিনামূল্যে পরিকল্পনায় ফিরে আসবেন। 15GB-এর বেশি আপনার ছবি এবং ভিডিও 30 দিনের জন্য ডাউনলোড করার জন্য রাখা হবে।',
  'plans.faqHowFamily': 'প্রো পরিকল্পনা কিভাবে কাজ করে?',
  'plans.faqHowFamilyAnswer': 'আপনি আপনার পরিবারের 4 জন সদস্য পর্যন্ত যোগ করতে পারেন। সবাই 500GB স্টোরেজ শেয়ার করে এবং Chatyy One-এর সমস্ত সুবিধা পায়। প্রতিটি ব্যক্তির নিজস্ব ব্যক্তিগত স্থান আছে — কেউ অন্যের ফাইল দেখতে পায় না।',
  'plans.faqChangePlanAnswer': 'হ্যাঁ! যদি আপনি Plus থেকে Pro-তে আপগ্রেড করেন, তবে কেবলমাত্র অনুপাতিক পার্থক্য চার্জ করা হবে। যদি আপনি ডাউনগ্রেড করেন, তবে বর্তমান পরিকল্পনা সময়সীমা শেষ হওয়া পর্যন্ত সক্রিয় থাকবে।',
  'plans.faqCardDeclined': 'আমার কার্ড বাতিল হয়েছে, আমি কি করব?',
  'plans.faqCardDeclinedAnswer': 'আপনার কাছে আপনার কার্ড আপডেট করার জন্য 7 দিন সময় আছে। এই সময়ের মধ্যে, আপনার সমস্ত সুবিধা কার্যকর থাকবে। 7 দিন পরে, পরিকল্পনা বিনামূল্যে ফিরে আসবে।',
  'plans.faqDataSafe': 'আমার ডেটা কি নিরাপদ?',
  'plans.faqDataSafeAnswer': 'হ্যাঁ! আপনার পেমেন্টের তথ্য এন্ড-টু-এন্ড এনক্রিপশনের সাথে প্রক্রিয়া করা হয়। আমরা আপনার কার্ডের নম্বর সংরক্ষণ করি না — কেবল আপনার রেফারেন্সের জন্য শেষ 4 ডিজিট।',
